use super::{document::{self,State},playback};
use serde_json::{json,Value};
fn edit(s:&mut State,hook:&str,mut v:Value)->Value{v["document_revision"]=json!(s.revision);document::dispatch(s,hook,&v).unwrap()}
fn state()->State{let mut s=State::default();edit(&mut s,"PutTrack",json!({"id":"m","name":"Midi","kind":"midi"}));edit(&mut s,"SetTrackMix",json!({"id":"m","output_bus_l":"L","output_bus_r":"R"}));s}
fn capture(s:&mut State,at:u64,frames:usize,events:Value){edit(s,"CaptureInput",json!({"sample_rate":8000,"capture_start_frame":at,"timeline_start_frame":0,"frames":frames,"playing":false,"recording":false,"live_inputs":{"physical":[]},"midi_events":events}));}
fn render(s:&State,at:u64,frames:usize)->Value{playback::render(s,&json!({"sample_rate":8000,"start_frame":0,"frames":frames,"instrument":"cardinal_sine","monitor_only":true,"capture_start_frame":at})).unwrap()}
fn event(at:u64,velocity:f64)->Value{json!({"capture_frame":at,"track":"m","pitch":69,"velocity":velocity})}
#[test]fn midi_live_monitor_sounds_while_stopped_and_follows_off_auto_in(){let mut s=state();capture(&mut s,0,512,json!([event(0,1.)]));let heard=render(&s,0,512);assert!(heard["master_stereo"].as_array().unwrap().iter().any(|v|v[0].as_f64().unwrap().abs()>0.01));edit(&mut s,"SetTrackMix",json!({"id":"m","input_monitor_mode":0}));let silent=render(&s,0,512);assert!(silent["master_stereo"].as_array().unwrap().iter().all(|v|v[0]==0.&&v[1]==0.));edit(&mut s,"SetTrackMix",json!({"id":"m","input_monitor_mode":1,"arm_mode":3}));assert_eq!(render(&s,0,512)["master_stereo"],heard["master_stereo"]);edit(&mut s,"SetTrackMix",json!({"id":"m","arm_mode":0}));assert_eq!(render(&s,0,512)["master_stereo"],silent["master_stereo"]);}
#[test]fn midi_live_phase_and_note_off_survive_block_boundaries(){let mut a=state();capture(&mut a,0,512,json!([event(0,1.),event(100,0.)]));let whole=render(&a,0,512);let mut b=state();capture(&mut b,0,256,json!([event(0,1.),event(100,0.)]));let first=render(&b,0,256);capture(&mut b,256,256,json!([]));let second=render(&b,256,256);let joined=first["master_stereo"].as_array().unwrap().iter().chain(second["master_stereo"].as_array().unwrap()).cloned().collect::<Vec<_>>();assert_eq!(whole["master_stereo"],json!(joined));let offline=playback::render(&b,&json!({"sample_rate":8000,"start_frame":0,"frames":256,"instrument":"cardinal_sine"})).unwrap();assert!(offline["master_stereo"].as_array().unwrap().iter().all(|v|v[0]==0.&&v[1]==0.));}
#[test]fn midi_preview_bypasses_keyboard_monitor_switch(){let mut s=state();edit(&mut s,"SetTrackMix",json!({"id":"m","input_monitor_mode":0}));let mut e=event(0,1.);e["source"]=json!("preview");capture(&mut s,0,512,json!([e]));assert!(render(&s,0,512)["master_stereo"].as_array().unwrap().iter().any(|v|v[0].as_f64().unwrap().abs()>0.01));}
